    28	// CatalogSearcher searches a private registry by walking /v2/_catalog and
    29	// filtering names client-side; the query is never sent to the registry.
    30	type CatalogSearcher struct {
    31		// List overrides oci.ListCatalogContext when set (tests).
    32		List CatalogLister
    33	}
    34	
    35	// Search implements Searcher.
    36	func (c CatalogSearcher) Search(ctx context.Context, t Target, q Query) ([]Image, bool, error) {
    37		text := strings.TrimSpace(q.Text)
    38		if utf8.RuneCountInString(text) < CatalogMinQueryRunes {
    39			return nil, false, ErrQueryTooShort
    40		}
    41		list := c.List
    42		if list == nil {
    43			list = oci.ListCatalogContext
    44		}
    45		names, truncated, err := walkCatalog(ctx, t, list)
    46		if err != nil {
    47			return nil, false, err
    48		}
    49		if len(names) == 0 {
    50			return nil, truncated, nil
    51		}
    52		prefix := strings.Trim(t.RepoPrefix, "/")
    53		needle := strings.ToLower(text)
    54		var all []Image
    55		sawPrefix := false
    56		for _, name := range names {
    57			rest := name
    58			if prefix != "" {
    59				var ok bool
    60				if rest, ok = strings.CutPrefix(name, prefix+"/"); !ok {
    61					continue
    62				}
    63				sawPrefix = true
    64			}
    65			if !validRepoPath(name) {
    66				continue
    67			}
    68			if strings.Contains(strings.ToLower(rest), needle) {
    69				all = append(all, Image{EntryKey: t.EntryKey, Name: rest, Repo: name})
    70			}
    71		}
    72		if prefix != "" && !sawPrefix {
    73			if truncated {
    74				return nil, true, nil
    75			}
    76			return nil, false, fmt.Errorf("%w (prefix %q)", ErrPrefixNotInCatalog, prefix)
    77		}
    78		slices.SortStableFunc(all, func(a, b Image) int {
    79			if d := MatchTier(text, a.Name) - MatchTier(text, b.Name); d != 0 {
    80				return d
    81			}
    82			if d := strings.Compare(strings.ToLower(a.Name), strings.ToLower(b.Name)); d != 0 {
    83				return d
    84			}
    85			return strings.Compare(a.Repo, b.Repo)
    86		})
    87		limit := CatalogMaxRows
    88		if q.Limit > 0 && q.Limit < limit {
    89			limit = q.Limit
    90		}
    91		cut := len(all) > limit
    92		if cut {
    93			all = all[:limit]
    94		}
    95		return all, truncated || cut, nil
    96	}
